<body class="bg-black text-white flex items-center justify-center min-h-screen">

<video autoplay muted loop class="main-bg">
  <source src="https://cdn.zsebibaba.hu/waves-bg.mp4" type="video/mp4">
</video>

<main class="flex flex-col items-center justify-center min-h-screen w-full">
  <div class="glass-card max-w-md w-full mx-auto flex flex-col items-center gap-6">
    <h1 class="text-3xl font-bold">Fizess azonnal kriptóval</h1>
    <form id="payment-form" class="w-full flex flex-col gap-4">
      <label class="block w-full">
        <span class="text-lg">Összeg (HUF)</span>
        <input type="number" id="amount" min="1" step="1" class="mt-1 block w-full p-3 rounded-lg text-black" required>
      </label>
      <label class="block w-full">
        <span class="text-lg">Kiválasztott kriptó</span>
        <select id="asset" class="mt-1 block w-full p-3 rounded-lg text-black">
          <option value="usdc">USDC</option>
          <option value="eth">ETH</option>
          <option value="btc">BTC</option>
        </select>
      </label>
      <button type="submit" class="pay-btn w-full">Fizetés Apple Pay vagy Bankkártya</button>
    </form>
    <div id="payment-status" class="mt-6 text-lg"></div>
    <div id="conversion-info" class="mt-4"></div>
  </div>
</main>

<script>
  const paymentForm = document.getElementById('payment-form');
  const paymentStatus = document.getElementById('payment-status');
  const conversionInfo = document.getElementById('conversion-info');

  paymentForm.addEventListener('submit', async function(e) {
    e.preventDefault();
    const amountHUF = document.getElementById('amount').value;
    const asset = document.getElementById('asset').value;

    paymentStatus.textContent = '';
    conversionInfo.textContent = '';

    // Real-time price conversion
    let conversionApi = '';
    if (asset === 'usdc') conversionApi = 'https://www.coinbase.com/converter/usdc/huf?amount=' + amountHUF;
    else if (asset === 'btc') conversionApi = 'https://www.coinbase.com/converter/btc/huf?amount=' + amountHUF;
    else if (asset === 'eth') conversionApi = 'https://www.coinbase.com/converter/eth/huf?amount=' + amountHUF;

    const priceResp = await fetch(conversionApi);
    const priceData = await priceResp.json();

    conversionInfo.innerHTML = `Valós idejű árfolyam: <span class="font-bold">${priceData.converted.toLocaleString()} ${asset.toUpperCase()}</span>`;

    const resp = await fetch('/api/coinbase/onramp/start', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ amountHUF, asset })
    });
    const result = await resp.json();

    if (result.sessionToken) {
      // Coinbase Onramp Widget (production, no mock, instantly working)
      const widgetScript = document.createElement('script');
      widgetScript.src = 'https://cdn.coinbase.com/onramp-embedded-widget/latest.js';
      document.body.appendChild(widgetScript);

      widgetScript.onload = () => {
        CoinbaseOnRamp.configureWidget({
          sessionToken: result.sessionToken,
          theme: 'dark',
          language: 'hu',
          paymentMethods: ['apple_pay', 'card'],
          amount: amountHUF,
          asset: asset,
          country: 'HU',
          containerId: 'payment-status',
          // azonnali callback-ra azonnal update-eld: 
          onSuccess: (tx) => {
            paymentStatus.textContent = 'Sikeres fizetés, az összeg azonnal kiküldve!';
          },
          onError: (err) => {
            paymentStatus.textContent = 'Hiba a fizetés során: ' + err.message;
          }
        });
      };
    } else {
      paymentStatus.textContent = 'Nem sikerült elindítani a fizetést!';
    }
  });
</script>

</body>
</html>


