javascript
const express = require("express");
const axios = require("axios");
const cors = require("cors");
require("dotenv").config();
const path = require("path");

const app = express();
app.use(express.json());
app.use(cors());

app.use(express.static(path.join(__dirname, ".")));

app.post("/api/coinbase/onramp/start", async (req, res) => {
  try {
    const { amountHUF, asset } = req.body;
    const quoteResp = await axios.get("https://api.developer.coinbase.com/onramp/v1/buy/quote", {
      headers: { Authorization: `Bearer ${process.env.COINBASE_API_KEY}` },
      params: {
        amount: amountHUF,
        payment_currency: "HUF",
        asset,
        country: "HU"
      }
    });
    const quoteId = quoteResp.data.id;
    const sessionResp = await axios.post("https://api.developer.coinbase.com/onramp/v1/session", {
      quoteId
    }, {
      headers: { Authorization: `Bearer ${process.env.COINBASE_API_KEY}` }
    });
    res.json({
      sessionToken: sessionResp.data.token
    });
  } catch (e) {
    res.status(500).json({ error: "Coinbase API error", message: e.message });
  }
});

app.listen(3000);


